// 分页工具（有 bug）

export interface PageResult<T> {
  items: T[]
  page: number        // 当前页码（1-based）
  totalPages: number  // 总页数
  totalItems: number  // 总条目数
}

// 对数组分页
// page 是 1-based（第 1 页是首页）
// pageSize 是每页条目数
export function paginate<T>(arr: T[], page: number, pageSize: number): PageResult<T> {
  const totalItems = arr.length
  // bug：这里用 Math.floor 导致最后一页丢失
  const totalPages = Math.floor(totalItems / pageSize)
  if (totalPages === 0) {
    return { items: arr, page: 1, totalPages: 1, totalItems }
  }

  // bug：起始索引算错了（page 直接乘 pageSize，没减 1）
  const startIndex = page * pageSize
  const endIndex = startIndex + pageSize
  const items = arr.slice(startIndex, endIndex)

  return { items, page, totalPages, totalItems }
}

